package com.paicli.state;

import java.sql.*;import java.util.*;

public final class McpToolCatalogStore {
 private final Connection c; private final McpToolStore tools; public McpToolCatalogStore(Connection c,McpToolStore tools){this.c=c;this.tools=tools;}
 public void createBuildingCatalog(String id,String session,String manifest,String server,String protocol,String hash,int pages,int totalBytes)throws SQLException{try(PreparedStatement check=c.prepareStatement("SELECT 1 FROM mcp_sessions WHERE session_id=? AND manifest_id=? AND server_id=?")){check.setString(1,session);check.setString(2,manifest);check.setString(3,server);try(ResultSet r=check.executeQuery()){if(!r.next())throw new IllegalArgumentException("catalog does not match session manifest/server");}}try(PreparedStatement s=c.prepareStatement("INSERT INTO mcp_tool_catalogs(catalog_id,session_id,manifest_id,server_id,protocol_version,catalog_hash,status,page_count,tool_count,total_schema_bytes) VALUES(?,?,?,?,?,?,'BUILDING',?,0,?)")){s.setString(1,id);s.setString(2,session);s.setString(3,manifest);s.setString(4,server);s.setString(5,protocol);s.setString(6,McpStoreSupport.hash(hash,"catalogHash"));s.setInt(7,pages);s.setInt(8,totalBytes);s.executeUpdate();}}
 public synchronized boolean acquireBuildingCatalog(String id,String session,String manifest,String server,String protocol)throws SQLException{
  Optional<CatalogRecord> existing=findBySession(session); if(existing.isPresent())return false;
  try{createBuildingCatalog(id,session,manifest,server,protocol,buildingHash(id),0,0);return true;}
  catch(SQLException e){if(findBySession(session).isPresent())return false;throw e;}
 }
 public synchronized void freezeCatalogAtomically(String id,List<McpToolStore.ToolRecord> records,String hash,int pages,int totalBytes)throws SQLException{
  boolean auto=c.getAutoCommit();c.setAutoCommit(false);try{
   String provisional=buildingHash(id);
   try(PreparedStatement check=c.prepareStatement("SELECT 1 FROM mcp_tool_catalogs WHERE catalog_id=? AND status='BUILDING' AND catalog_hash=?")){check.setString(1,id);check.setString(2,provisional);try(ResultSet r=check.executeQuery()){if(!r.next())throw new SQLException("catalog is not owned BUILDING artifact");}}
   for(var record:records)tools.insert(record);
   String session;try(PreparedStatement s=c.prepareStatement("UPDATE mcp_tool_catalogs SET catalog_hash=?,page_count=?,tool_count=?,total_schema_bytes=?,status='FROZEN',frozen_at=datetime('now') WHERE catalog_id=? AND status='BUILDING' AND catalog_hash=? RETURNING session_id")){s.setString(1,McpStoreSupport.hash(hash,"catalogHash"));s.setInt(2,pages);s.setInt(3,records.size());s.setInt(4,totalBytes);s.setString(5,id);s.setString(6,provisional);try(ResultSet r=s.executeQuery()){if(!r.next())throw new SQLException("catalog freeze ownership lost");session=r.getString(1);}}
   try(PreparedStatement s=c.prepareStatement("UPDATE mcp_sessions SET catalog_id=? WHERE session_id=? AND status='READY' AND catalog_id IS NULL")){s.setString(1,id);s.setString(2,session);if(s.executeUpdate()!=1)throw new SQLException("READY session already bound or unavailable");}
   c.commit();
  }catch(Exception e){c.rollback();if(e instanceof SQLException x)throw x;throw e;}finally{c.setAutoCommit(auto);}
 }
 public void saveCatalogToolsAtomically(String catalog,List<McpToolStore.ToolRecord> records,String expectedHash)throws SQLException{boolean auto=c.getAutoCommit();c.setAutoCommit(false);try{for(var r:records)tools.insert(r);try(PreparedStatement s=c.prepareStatement("UPDATE mcp_tool_catalogs SET tool_count=? WHERE catalog_id=? AND status='BUILDING' AND catalog_hash=?")){s.setInt(1,records.size());s.setString(2,catalog);s.setString(3,expectedHash);if(s.executeUpdate()!=1)throw new SQLException("catalog not building or hash mismatch");}c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException x)throw x;throw e;}finally{c.setAutoCommit(auto);}}
 public void freezeCatalog(String id,String expectedHash)throws SQLException{boolean auto=c.getAutoCommit();c.setAutoCommit(false);try(PreparedStatement count=c.prepareStatement("SELECT tool_count,session_id,(SELECT count(*) FROM mcp_tools WHERE catalog_id=?) actual FROM mcp_tool_catalogs WHERE catalog_id=? AND status='BUILDING' AND catalog_hash=?")){count.setString(1,id);count.setString(2,id);count.setString(3,expectedHash);String session;try(ResultSet r=count.executeQuery()){if(!r.next()||r.getInt("tool_count")!=r.getInt("actual"))throw new SQLException("catalog/tool artifact mismatch");session=r.getString("session_id");}try(PreparedStatement s=c.prepareStatement("UPDATE mcp_tool_catalogs SET status='FROZEN',frozen_at=datetime('now') WHERE catalog_id=? AND status='BUILDING'")){s.setString(1,id);if(s.executeUpdate()!=1)throw new SQLException("invalid catalog freeze");}try(PreparedStatement s=c.prepareStatement("UPDATE mcp_sessions SET catalog_id=? WHERE session_id=? AND catalog_id IS NULL")){s.setString(1,id);s.setString(2,session);if(s.executeUpdate()!=1)throw new SQLException("session already bound to a catalog");}c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(auto);}}
 public synchronized void markCatalogStale(String id)throws SQLException{transition(id,"FROZEN","STALE",null);}
 public synchronized void markCatalogInvalid(String id,String reason)throws SQLException{transition(id,"BUILDING","INVALID",reason);}
 private void transition(String id,String from,String to,String reason)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE mcp_tool_catalogs SET status=?,invalid_reason=?,stale_at=CASE WHEN ?='STALE' THEN datetime('now') ELSE stale_at END WHERE catalog_id=? AND status=?")){s.setString(1,to);s.setString(2,McpStoreSupport.optional(reason,4096));s.setString(3,to);s.setString(4,id);s.setString(5,from);if(s.executeUpdate()!=1)throw new SQLException("invalid catalog transition");}}
 public Optional<CatalogRecord> findById(String id)throws SQLException{return one("catalog_id=?",id);}
 public Optional<CatalogRecord> findBySession(String session)throws SQLException{return one("session_id=?",session);}
 public Optional<CatalogRecord> findFrozenCatalog(String session)throws SQLException{return one("session_id=? AND status='FROZEN'",session);}
 public Optional<CatalogRecord> findCatalogByHash(String server,String hash)throws SQLException{return one("server_id=? AND catalog_hash=?",server,hash);}
 private Optional<CatalogRecord> one(String where,String...p)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT * FROM mcp_tool_catalogs WHERE "+where)){for(int i=0;i<p.length;i++)s.setString(i+1,p[i]);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(new CatalogRecord(r.getString("catalog_id"),r.getString("session_id"),r.getString("manifest_id"),r.getString("server_id"),r.getString("protocol_version"),r.getString("catalog_hash"),r.getString("status"),r.getInt("page_count"),r.getInt("tool_count"),r.getInt("total_schema_bytes"))):Optional.empty();}}}
 public record CatalogRecord(String catalogId,String sessionId,String manifestId,String serverId,String protocolVersion,String catalogHash,String status,int pageCount,int toolCount,int totalSchemaBytes){}
 private static String buildingHash(String id){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(("building:"+id).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
